(function () {
  var BOT_URL = "https://turismo-avatar-bot-446018569219.southamerica-west1.run.app/";
  var bubble = document.getElementById('ta-chat-bubble');
  var wrap = document.getElementById('ta-chat-frame-wrap');
  var frame = document.getElementById('ta-chat-frame');
  var loaded = false;

  // Función que maneja la lógica de abrir y cerrar
  function toggleChat() {
    var isOpen = wrap.classList.toggle('open');
    if (isOpen && !loaded) {
      frame.src = BOT_URL;
      loaded = true;
    }
    bubble.textContent = isOpen ? '✕' : '💬';
  }

  // Evento al hacer clic manualmente
  bubble.addEventListener('click', toggleChat);

  // Auto-apertura después de 5 segundos (5000 milisegundos)
  setTimeout(function() {
    // Solo se abre automáticamente si el usuario no lo ha abierto antes por su cuenta
    if (!wrap.classList.contains('open')) {
      toggleChat();
    }
  }, 5000);

})();

